import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import {
  batchTransitionRoot,
  batchTransitionRootV1,
  batchTransitionRootV2,
  bytesToHex,
  fraudProof,
  RestClient,
  transitionRootVersionFor,
  transitionRootVersionForBatch,
} from "../src/index";

// Vectors generated by calling the chain's own BatchTransitionRoot.
const golden = JSON.parse(
  readFileSync(fileURLToPath(new URL("../../_fixtures/golden.json", import.meta.url)), "utf8"),
);
const t = golden.transitionRoot;
const input = {
  chainId: t.chainId,
  rollupId: t.rollupId,
  prevStateRoot: t.prevStateRoot,
  dataHash: t.dataHash,
  txCount: t.txCount,
  withdrawalsRoot: t.withdrawalsRoot,
};

describe("batch transition root (chain vectors)", () => {
  it("v1 matches the chain", () => {
    expect(bytesToHex(batchTransitionRootV1(input))).toBe(t.v1);
    expect(bytesToHex(batchTransitionRootV1({ prevStateRoot: t.prevStateRoot, txCount: 1 }))).toBe(t.emptyBatch.v1);
  });

  it("v2 matches the chain and binds the chain id", () => {
    expect(bytesToHex(batchTransitionRootV2(input))).toBe(t.v2);
    expect(bytesToHex(batchTransitionRoot({ ...input, chainId: t.v2OtherChain.chainId }, "v2"))).toBe(
      t.v2OtherChain.root,
    );
    const empty = { chainId: t.chainId, rollupId: t.rollupId, prevStateRoot: t.prevStateRoot, txCount: 1 };
    expect(bytesToHex(batchTransitionRootV2(empty))).toBe(t.emptyBatch.v2);
  });

  it("v2 refuses a missing chain id or rollup id, and a malformed withdrawals root", () => {
    expect(() => batchTransitionRootV2({ ...input, chainId: undefined })).toThrow(/chain id/);
    expect(() => batchTransitionRootV2({ ...input, withdrawalsRoot: "abcd" })).toThrow(/empty or 32 bytes/);
  });
});

describe("transitionRootVersionFor", () => {
  const rest = (reply: () => Response) => new RestClient("http://node", { fetch: async () => reply() });
  const features = (enabled: boolean) =>
    new Response(JSON.stringify({ features: [{ name: "rdk-withdrawals-binding", enabled }] }));

  it("is v2 once the chain enables rdk-withdrawals-binding", async () => {
    expect(await transitionRootVersionFor(rest(() => features(true)))).toBe("v2");
    expect(await transitionRootVersionFor(rest(() => features(false)))).toBe("v1");
  });

  it("is v1 on a chain without the feature route", async () => {
    expect(await transitionRootVersionFor(rest(() => new Response("{}", { status: 501 })))).toBe("v1");
  });

  it("raises other errors instead of guessing", async () => {
    await expect(
      transitionRootVersionFor(rest(() => new Response("{}", { status: 500, statusText: "Internal" }))),
    ).rejects.toThrow(/500/);
  });
});

describe("fraudProof", () => {
  it("is prev_state_root || correct_state_root", () => {
    const p = fraudProof("11".repeat(32), "22".repeat(32));
    expect(bytesToHex(p)).toBe("11".repeat(32) + "22".repeat(32));
    expect(() => fraudProof("11", "22".repeat(32))).toThrow(/32-byte/);
  });
});

describe("transitionRootVersionForBatch", () => {
  const rest = (height: number) => ({ getAppliedPlanHeight: async () => height });

  it("is v2 from the applied height on, the upgrade block included", async () => {
    expect(await transitionRootVersionForBatch(rest(8_890_800), { submittedAt: 8_890_800 })).toBe("v2");
    expect(await transitionRootVersionForBatch(rest(8_890_800), { submittedAt: 8_890_799 })).toBe("v1");
  });

  it("is v1 while the upgrade has not applied", async () => {
    expect(await transitionRootVersionForBatch(rest(0), { submittedAt: 9_000_000 })).toBe("v1");
  });

  it("trusts the batch's own flag when the node serves it", async () => {
    expect(await transitionRootVersionForBatch(rest(0), { submittedAt: 1, withdrawalsBound: true })).toBe("v2");
  });

  it("reads the applied plan height from the chain", async () => {
    const r = new RestClient("http://node", {
      fetch: async (url: string) =>
        new Response(JSON.stringify({ height: String(url).endsWith("/v3.2.5") ? "8890800" : "0" })),
    });
    expect(await r.getAppliedPlanHeight("v3.2.5")).toBe(8_890_800);
  });
});
